'use strict';
const fs = require('fs');
const path = require('path');
const { renderArticlePage, stripTags } = require('./lib/article-page');
const { imageSize } = require('./lib/article-skeleton');
const ROOT = path.resolve(__dirname, '..');
const RUN = 'yuka-autopilot-20261029-0501';
const credit = 'Foto: Dokumentasi YUKA (Yayasan Ukhuwah Kaffah Amanatullah).';
const img = (file, alt, caption) => `<figure><img src="../${file}" alt="${alt}" loading="lazy" width="1200" height="900"><figcaption>${caption}<span class="kredit">${credit}</span></figcaption></figure>`;
const p = (text) => `<p>${text}</p>`;
const h2 = (id, title) => `<h2 id="${id}">${title}</h2>`;
const h3 = (title) => `<h3>${title}</h3>`;
const il = (slug, label) => `<a href="../${slug}">${label}</a>`;
const ext = (url, label) => `<a href="${url}" target="_blank" rel="noopener">${label}</a>`;
const ul = (items) => `<ul>${items.map((x) => `<li>${x}</li>`).join('')}</ul>`;
const faqHtml = (faq) => `${h2('faq', 'Pertanyaan yang Sering Diajukan')}<div class="faq-list">${faq.map((x) => `${h3(x.q)}${p(x.a)}`).join('')}</div>`;
const table = (headers, rows) => `<table><thead><tr>${headers.map((x) => `<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((x) => `<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const toc = (items) => `<nav class="toc" aria-label="Daftar Isi"><h3>Daftar Isi</h3><ol>${items.map(([id, label]) => `<li><a href="#${id}">${label}</a></li>`).join('')}</ol></nav>`;
const bodyStart = (answer, intro, items) => `<div class="jawaban-singkat"><p>${answer}</p></div>${p(intro)}${toc(items)}`;
function makeHero(file, alt, caption) {
  const size = imageSize(path.join(ROOT, file));
  if (!size || size.h > size.w) throw new Error(`hero tidak valid ${file}`);
  return { file, w: size.w, h: size.h, alt, caption, credit };
}
function makeBodyFigure(file, alt, caption) { return img(file, alt, caption); }
function articleBase({slug, title, metaDesc, keyword, datePublished, dateDisplay, image, bodyHtml, faq, related, sources, tags}) {
  const data = {
    slug, titleTag: title, metaDesc, keywords: keyword, ogTitle: title, ogDesc: metaDesc,
    datePublished, dateModified: datePublished, dateDisplay, readTime: '14 menit baca', category: 'Pendidikan',
    h1: title, crumb: title, about: [keyword, 'Pendidikan inklusi', 'Anak berkebutuhan khusus'], image, bodyHtml, faq,
    related, tags, sources,
    sourcesCheckedNote: 'Sumber resmi diperiksa pada 29 Oktober 2026. Artikel ini bersifat edukasi umum dan tidak menggantikan asesmen atau keputusan profesional.',
  };
  const html = renderArticlePage(data).replace('<article class="article-content">', `<article class="article-content" data-revision-marker="${RUN}-${slug}">`);
  fs.writeFileSync(path.join(ROOT, 'artikel', `${slug}.html`), html, 'utf8');
  const out = { slug, bytes: Buffer.byteLength(html), qualityWords: stripTags(bodyHtml).split(/\s+/).filter(Boolean).length, faq: faq.length, sources: sources.length, bodyImages: (bodyHtml.match(/<img\b/gi) || []).length, datePublished };
  console.log(JSON.stringify(out));
  return out;
}

const pbsFaq = [
  { q: 'Apa itu positive behavior support pada anak?', a: 'Positive behavior support adalah pendekatan terencana untuk memahami alasan sebuah perilaku muncul, mencegah situasi pemicu, mengajarkan keterampilan pengganti, dan memberi penguatan ketika anak menggunakan keterampilan yang sesuai. Fokusnya bukan menghukum anak, melainkan membangun lingkungan dan dukungan yang membuat perilaku adaptif lebih mudah dilakukan.' },
  { q: 'Apakah PBS sama dengan hukuman atau hadiah?', a: 'Tidak. PBS memakai penguatan positif sebagai bagian dari pengajaran, tetapi bukan sekadar memberi hadiah. Tim perlu mengajarkan perilaku yang diharapkan, menjelaskan kapan keterampilan itu digunakan, memberi umpan balik yang spesifik, dan meninjau data. Konsekuensi yang aman tetap dapat disusun, tetapi tidak boleh merendahkan, menyakiti, atau menghilangkan hak anak.' },
  { q: 'Apakah PBS hanya untuk anak autis?', a: 'Tidak. PBS dapat dipakai untuk berbagai anak yang membutuhkan dukungan sosial, emosional, komunikasi, atau perilaku, termasuk anak tanpa diagnosis. Pada anak berkebutuhan khusus, rencana perlu disesuaikan dengan komunikasi, sensorik, kemampuan motorik, kesehatan, dan konteks keluarga. Label diagnosis tidak boleh menjadi satu-satunya dasar menentukan intervensi.' },
  { q: 'Siapa yang menyusun rencana dukungan perilaku?', a: 'Rencana terbaik disusun bersama oleh anak sesuai kemampuannya, orang tua, guru, pendamping, dan profesional yang relevan. Untuk kebutuhan intensif, asesmen perilaku fungsional dan rencana dukungan sebaiknya melibatkan tenaga yang kompeten. Orang tua perlu mendapat penjelasan tujuan, cara mencatat data, batas keselamatan, serta cara menyampaikan keberatan.' },
  { q: 'Berapa lama hasil PBS terlihat?', a: 'Tidak ada durasi yang sama untuk semua anak. Tim perlu menentukan indikator awal, mencoba strategi secara konsisten, lalu meninjau data dalam periode yang disepakati. Perubahan kecil seperti anak meminta jeda sebelum menangis, menyelesaikan satu langkah kegiatan, atau menerima transisi dengan bantuan juga penting. Jika tidak ada kemajuan, strategi dan dugaan fungsi perilaku perlu ditinjau.' },
  { q: 'Apa yang dapat dilakukan orang tua di rumah?', a: 'Orang tua dapat membuat rutinitas mudah diprediksi, memberi instruksi singkat, menawarkan pilihan terbatas, mengajarkan cara meminta bantuan, dan memberi pujian spesifik ketika anak memakai keterampilan yang diharapkan. Catat situasi sebelum perilaku, perilaku yang terlihat, dan respons sesudahnya. Jangan menggunakan cara yang menyakitkan atau mempermalukan anak.' },
  { q: 'Kapan keluarga perlu mencari bantuan profesional?', a: 'Cari bantuan ketika perilaku berisiko menimbulkan cedera, mengganggu makan atau tidur, membuat anak tidak dapat mengikuti kegiatan utama, atau keluarga kesulitan menjaga keselamatan. Konsultasi juga diperlukan jika ada dugaan nyeri, gangguan tidur, efek obat, masalah komunikasi, atau kondisi kesehatan lain. Bantuan profesional tidak berarti orang tua gagal.' },
];
let pbsBody = bodyStart(
  'Positive Behavior Support atau PBS adalah pendekatan untuk membantu anak membangun perilaku adaptif dengan memahami fungsi perilaku, mengatur lingkungan, mengajarkan keterampilan pengganti, dan memakai data untuk menilai kemajuan. Untuk anak berkebutuhan khusus, PBS perlu disusun bersama keluarga, sekolah, dan profesional yang relevan. Tujuannya bukan membuat anak selalu diam, tetapi meningkatkan komunikasi, partisipasi, rasa aman, dan keberfungsian sosial.',
  'Istilah positive behavior support sering muncul ketika orang tua atau guru mencari cara menghadapi tantrum, penolakan aktivitas, agresi, melarikan diri, atau kesulitan berpindah kegiatan. Tantangan itu perlu dibaca sebagai informasi. Anak mungkin belum memiliki cara yang efektif untuk meminta jeda, menolak tugas, mencari perhatian, mengatasi sensasi, atau menyampaikan rasa sakit. Karena itu, rencana dukungan perlu mengubah kondisi di sekitar anak sekaligus mengajarkan respons baru. Pendekatan ini berbeda dari upaya memaksa anak mengikuti aturan tanpa memahami kebutuhannya. Kerangka PBIS dari Center on PBIS menjelaskan dukungan bertingkat, dari dukungan universal sampai intervensi individual berbasis fungsi.',
  [['apa-itu-pbs','Apa itu PBS'],['mengapa-penting','Mengapa penting untuk anak ABK'],['prinsip','Prinsip utama'],['asesmen-fungsi','Memahami fungsi perilaku'],['rencana','Menyusun rencana'],['praktik-rumah-sekolah','Praktik di rumah dan sekolah'],['data','Menggunakan data'],['faq','FAQ']]
);
pbsBody += h2('apa-itu-pbs', 'Apa Itu Positive Behavior Support?') +
p('PBS merupakan kerangka dukungan yang melihat perilaku dalam konteks. Tim tidak berhenti pada pertanyaan, "Bagaimana menghentikan perilaku ini?" Pertanyaan yang lebih membantu adalah, "Apa yang sedang berusaha disampaikan anak, kondisi apa yang mendahuluinya, dan keterampilan apa yang dapat diajarkan?" Jawabannya dapat mengarah pada perubahan jadwal, cara memberi instruksi, akses terhadap komunikasi, penyesuaian tuntutan, atau penguatan yang lebih jelas. Pendekatan ini tidak berarti semua perilaku harus diterima tanpa batas. Keselamatan tetap menjadi prioritas, tetapi respons orang dewasa harus diarahkan pada pencegahan, pengajaran, dan pemulihan.' ) +
p('Pada tingkat universal, sekolah dapat membangun aturan yang singkat dan positif, mengajarkan aturan di setiap tempat, memberi umpan balik spesifik, serta memantau apakah dukungan berlaku adil. Pada tingkat tertarget, anak yang belum berhasil dengan dukungan umum mendapat latihan tambahan, kelompok kecil, atau sistem pemantauan yang lebih sering. Pada tingkat intensif, tim menyusun dukungan individual berdasarkan asesmen yang lebih rinci. Pembaca dapat melihat hubungan antara pendidikan inklusi dan dukungan perilaku melalui artikel '+il('pendidikan-inklusi','pendidikan inklusi')+' serta artikel '+il('classroom-management-kelas-inklusi','pengelolaan kelas inklusi')+'.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_120255.webp','Kegiatan belajar anak dalam lingkungan kelompok yang terstruktur','Dokumentasi kegiatan belajar YUKA di lingkungan kelompok. Foto ini bukan ilustrasi diagnosis atau hasil intervensi tertentu.') +
h2('mengapa-penting', 'Mengapa PBS Penting untuk Anak Berkebutuhan Khusus?') +
p('Anak berkebutuhan khusus dapat menghadapi hambatan komunikasi, pemrosesan bahasa, fungsi eksekutif, sensorik, motorik, atau regulasi emosi. Hambatan tersebut dapat membuat instruksi biasa terasa terlalu cepat, terlalu panjang, atau tidak jelas. Anak kemudian memakai cara yang paling tersedia untuk menyampaikan kebutuhan. Jika orang dewasa hanya memberi hukuman, anak belum tentu belajar cara baru. PBS membantu tim memecah situasi menjadi bagian yang dapat diamati, kemudian memperbaiki dukungan di setiap bagian.' ) +
p('Pendekatan ini juga membantu menjaga martabat anak. Perilaku tidak dipakai untuk memberi label seperti malas, nakal, atau tidak mau belajar. Tim membedakan antara niat dan dampak. Anak mungkin tidak bermaksud mengganggu, tetapi perilakunya tetap bisa membahayakan. Dengan bahasa yang netral, keluarga dan sekolah dapat membahas kebutuhan tanpa menyalahkan. Dalam praktik, target yang baik bersifat fungsional, misalnya anak dapat meminta istirahat dengan kartu, menunjuk pilihan, menunggu giliran selama waktu tertentu, atau kembali ke kegiatan setelah bantuan visual.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_121352.webp','Kelompok anak dan pendamping dalam kegiatan bersama','Dokumentasi kegiatan kebersamaan YUKA. Dukungan perilaku sebaiknya memperhatikan relasi anak dengan keluarga dan komunitas.') +
h2('prinsip', 'Prinsip Utama yang Perlu Dijaga') +
table(['Prinsip','Makna praktis','Contoh pertanyaan'],[
['Berbasis fungsi','Cari kebutuhan atau tujuan yang mungkin berada di balik perilaku.','Apa yang anak dapatkan atau hindari setelah perilaku muncul?'],
['Proaktif','Ubah pemicu dan siapkan dukungan sebelum masalah terjadi.','Apakah jadwal, pilihan, atau bantuan visual sudah tersedia?'],
['Mengajar keterampilan','Ajarkan respons pengganti yang dapat dilakukan anak.','Bagaimana anak meminta jeda atau bantuan?'],
['Positif dan bermartabat','Berikan penguatan yang jelas tanpa mempermalukan anak.','Apakah umpan balik menjelaskan perilaku yang berhasil?'],
['Berbasis data','Gunakan catatan sederhana untuk menilai kemajuan.','Apakah frekuensi, durasi, atau intensitas berubah?'],
['Kolaboratif','Samakan bahasa dan strategi lintas rumah, sekolah, dan layanan.','Siapa melakukan apa dan kapan strategi ditinjau?'],
]) +
p('Prinsip tersebut perlu diterapkan secara fleksibel. Anak tidak harus dipaksa memakai satu metode komunikasi jika metode itu belum dapat diakses. Pilihan dapat berupa bahasa lisan, gestur, gambar, tulisan, perangkat komunikasi, atau bantuan orang dewasa. Keluarga juga perlu memperhatikan budaya, rutinitas, sumber daya, dan kondisi rumah. Rencana yang terlalu rumit sering sulit dijalankan. Lebih baik memilih satu atau dua perubahan yang jelas, mengukur hasilnya, lalu menambah strategi secara bertahap.') +
h2('asesmen-fungsi', 'Cara Memahami Fungsi Perilaku') +
p('Asesmen perilaku fungsional atau functional behavior assessment membantu tim melihat pola sebelum, saat, dan sesudah perilaku. Catatan sederhana dapat memakai format A, B, C. A adalah antecedent atau kejadian sebelum perilaku, B adalah behavior atau perilaku yang terlihat, dan C adalah consequence atau respons sesudahnya. Catat fakta yang dapat dilihat, bukan penilaian seperti anak sengaja mencari masalah. Contoh catatan faktual adalah, "setelah instruksi menulis diberikan, anak menjatuhkan pensil, menangis dua menit, lalu tugas ditunda."') +
p('Dari beberapa catatan, tim dapat melihat dugaan fungsi. Perilaku mungkin berkaitan dengan meminta sesuatu, menghindari kegiatan, mencari perhatian, mendapatkan rangsangan sensorik, atau merespons rasa sakit dan kelelahan. Dugaan fungsi bukan diagnosis dan perlu diuji secara hati-hati. Pastikan kemungkinan medis tidak diabaikan. Artikel '+il('asesmen-abk','asesmen ABK')+' dapat membantu pembaca memahami pentingnya mengumpulkan informasi sebelum mengambil kesimpulan. Jika perilaku mengancam keselamatan, asesmen formal perlu dilakukan oleh tenaga yang kompeten.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_121356.webp','Anak dan pendamping mengikuti aktivitas kelompok','Dokumentasi aktivitas kelompok YUKA yang menunjukkan pentingnya dukungan sosial dalam kegiatan anak.') +
h2('rencana', 'Langkah Menyusun Rencana Dukungan') +
p('Mulai dengan memilih satu target yang penting dan dapat diamati. Hindari target yang terlalu umum seperti "anak harus lebih baik". Tuliskan kapan perilaku muncul, seberapa sering, berapa lama, dan dampaknya terhadap kegiatan. Setelah itu, tentukan keterampilan pengganti yang realistis. Jika anak berteriak saat ingin berhenti, target awal mungkin meminta jeda dengan kartu atau kata sederhana. Jika anak memukul ketika berebut, keterampilan pengganti dapat berupa meminta giliran, memakai timer, atau berpindah ke aktivitas menenangkan.') +
ul([
'Jelaskan rutinitas dan harapan dengan kalimat singkat, gambar, contoh, atau demonstrasi.',
'Kurangi pemicu yang tidak perlu, misalnya instruksi terlalu panjang, waktu tunggu tanpa informasi, atau perubahan jadwal mendadak.',
'Ajarkan keterampilan pengganti ketika anak tenang, bukan hanya ketika krisis sudah berlangsung.',
'Tentukan penguatan yang bermakna bagi anak, seperti pujian spesifik, akses aktivitas, pilihan, atau waktu bersama.',
'Tulis respons keselamatan yang singkat, konsisten, dan tidak mempermalukan anak.',
'Tentukan siapa yang mencatat data dan kapan tim meninjau rencana.',
]) +
p('Rencana perlu mencantumkan hal yang tidak boleh dilakukan. Jangan menahan makan, minum, toilet, komunikasi, atau kebutuhan dasar sebagai hukuman. Jangan memaksa kontak mata, menertawakan perilaku, atau menggunakan ancaman. Untuk anak yang mengalami kondisi kesehatan atau sedang memakai obat, perubahan perilaku perlu dibicarakan dengan tenaga kesehatan. Rencana yang baik juga memberi ruang bagi anak untuk beristirahat dan memulihkan diri setelah situasi sulit.') +
h2('praktik-rumah-sekolah', 'Contoh Praktik di Rumah dan Sekolah') +
p('Di rumah, keluarga dapat memakai papan jadwal sederhana untuk urutan bangun, makan, mandi, belajar, bermain, dan tidur. Beri peringatan sebelum transisi, misalnya lima menit lalu dua menit. Tawarkan dua pilihan yang sama-sama dapat diterima. Gunakan kalimat yang konsisten, seperti "Pertama simpan mainan, lalu pilih buku". Ketika anak meminta bantuan dengan cara yang disepakati, respons secepat mungkin bila aman. Pujian perlu menyebut perilakunya, misalnya "Kamu menunjukkan kartu jeda, jadi kita bisa berhenti dengan aman".') +
p('Di sekolah, guru dapat memeriksa apakah tempat duduk, suara, cahaya, jumlah tugas, dan waktu tunggu sesuai kebutuhan anak. Instruksi dapat dibagi menjadi langkah kecil. Tugas yang panjang dapat dibuat dalam beberapa bagian dengan tanda selesai yang terlihat. Pendamping sebaiknya tidak mengambil alih semua pekerjaan anak. Bantuan perlu dikurangi perlahan agar anak tetap mengembangkan kemandirian. Strategi tersebut dapat dihubungkan dengan '+il('adaptasi-soal-ujian-untuk-anak-abk','adaptasi pembelajaran')+' dan '+il('buddy-system-untuk-anak-abk-di-sekolah','buddy system di sekolah')+'.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_121400.webp','Pendamping dan anak berada dalam suasana kegiatan bersama','Dokumentasi suasana kebersamaan YUKA. Interaksi yang aman dan dapat diprediksi membantu anak mengikuti kegiatan.') +
h2('data', 'Menggunakan Data Tanpa Mengubah Anak Menjadi Angka') +
p('Data membantu tim memeriksa apakah rencana benar-benar bermanfaat. Pilih ukuran yang mudah dicatat, misalnya jumlah permintaan jeda yang sesuai, durasi mengikuti kegiatan, jumlah insiden yang memerlukan bantuan, atau waktu yang dibutuhkan untuk kembali tenang. Catat kondisi penting seperti tidur, sakit, perubahan jadwal, atau pergantian pendamping. Jangan membandingkan anak dengan anak lain. Bandingkan pola anak dengan dirinya sendiri dari waktu ke waktu.') +
p('Tinjau data dalam pertemuan singkat. Jika perilaku berkurang tetapi anak masih belum dapat berkomunikasi, target belum sepenuhnya tercapai. Jika strategi hanya berhasil dengan satu pendamping, tim perlu melatih orang lain agar dukungan lebih konsisten. Jika perilaku meningkat, jangan langsung menyimpulkan anak menolak. Periksa kembali tuntutan, akses komunikasi, kesehatan, kualitas tidur, dan apakah penguatan diberikan sesuai rencana. Center on PBIS menekankan penggunaan data untuk memilih, memantau, dan menyesuaikan dukungan secara berkelanjutan.') +
p('Perlu diingat bahwa keberhasilan PBS tidak selalu terlihat sebagai hilangnya semua perilaku yang dianggap sulit. Ukuran yang lebih bermakna dapat berupa meningkatnya kesempatan anak berkomunikasi, berkurangnya waktu pemulihan, bertambahnya partisipasi, atau berkurangnya kebutuhan bantuan. Tim juga perlu menilai apakah strategi terasa aman bagi anak. Jika strategi hanya berhasil karena anak takut, menahan diri, atau kehilangan akses komunikasi, strategi itu tidak memenuhi tujuan dukungan yang bermartabat. Tinjau suara anak melalui kata, gestur, pilihan, atau perubahan ekspresi yang dapat dipahami oleh orang yang mendampinginya.') +
p('Kolaborasi dapat dimulai dari satu lembar rencana yang berisi target, pemicu yang perlu dihindari, keterampilan pengganti, cara memberi bantuan, penguatan, dan respons keselamatan. Gunakan bahasa yang sama di rumah dan sekolah agar anak tidak harus mempelajari aturan yang bertentangan. Saat ada pergantian guru atau pendamping, jelaskan alasan di balik strategi, bukan hanya daftar instruksi. Dengan begitu, orang dewasa dapat menyesuaikan dukungan ketika konteks berubah tanpa menghilangkan tujuan utama, yaitu komunikasi, keamanan, kemandirian, dan partisipasi anak.') +
h2('kesimpulan', 'Kesimpulan') +
p('Positive Behavior Support membantu keluarga dan sekolah berpindah dari reaksi spontan menuju dukungan yang terencana. Anak dipandang sebagai individu yang perlu diajari keterampilan, diberi akses komunikasi, dan ditempatkan dalam lingkungan yang aman. Rencana yang baik menggabungkan pencegahan, pengajaran, penguatan, data, dan kolaborasi. Mulailah dari satu target kecil, pastikan strategi dapat dilakukan, lalu tinjau hasilnya bersama orang yang mengenal anak.') + faqHtml(pbsFaq);

const legalFaq = [
  { q: 'Apa yang dimaksud peraturan pemerintah tentang disabilitas?', a: 'Peraturan pemerintah tentang disabilitas adalah aturan pelaksana yang menerjemahkan mandat undang-undang ke dalam perencanaan, layanan, akomodasi, aksesibilitas, kesejahteraan sosial, dan mekanisme kelembagaan. Satu PP biasanya mengatur bidang tertentu. Karena itu, pembaca perlu melihat judul dan ruang lingkup aturan, bukan menganggap semua persoalan disabilitas diatur dalam satu dokumen.' },
  { q: 'PP mana yang mengatur akomodasi pendidikan?', a: 'PP Nomor 13 Tahun 2020 mengatur Akomodasi yang Layak untuk Peserta Didik Penyandang Disabilitas. Sekretariat Kabinet menjelaskan bahwa fasilitasi mencakup dukungan anggaran, sarana prasarana, pendidik dan tenaga kependidikan, serta kurikulum. Penerapannya tetap perlu melihat kondisi satuan pendidikan, ragam disabilitas, dan mekanisme layanan yang tersedia.' },
  { q: 'Apakah sekolah wajib menerima semua anak disabilitas?', a: 'Hak pendidikan dan prinsip nondiskriminasi perlu dibaca bersama ketentuan penyelenggaraan pendidikan dan kemampuan dukungan yang diwajibkan. Artikel ini tidak menggantikan nasihat hukum. Orang tua dapat meminta informasi tertulis tentang layanan, akomodasi, Unit Layanan Disabilitas, serta jalur pengaduan. Penempatan anak sebaiknya dibahas dengan mengutamakan kebutuhan dan hak anak.' },
  { q: 'Apa hubungan PP 70 Tahun 2019 dengan kebijakan daerah?', a: 'PP 70 Tahun 2019 membahas perencanaan, penyelenggaraan, dan evaluasi penghormatan, pelindungan, serta pemenuhan hak penyandang disabilitas. Kerangka ini menghubungkan perencanaan jangka panjang, rencana aksi, program, penganggaran, pemantauan, dan evaluasi. Pemerintah daerah perlu menerjemahkannya melalui dokumen dan program yang sesuai kewenangannya.' },
  { q: 'Apa itu Unit Layanan Disabilitas?', a: 'Unit Layanan Disabilitas adalah bagian dari institusi yang menyediakan layanan dan fasilitas bagi penyandang disabilitas sesuai bidangnya. Dalam pendidikan, unit ini dapat membantu asesmen kebutuhan, koordinasi dukungan, dan peningkatan kapasitas. Dalam ketenagakerjaan, PP Nomor 60 Tahun 2020 mengatur ULD bidang ketenagakerjaan di tingkat provinsi dan kabupaten atau kota.' },
  { q: 'Bagaimana orang tua memakai aturan ini saat berdiskusi dengan sekolah?', a: 'Orang tua dapat membawa pertanyaan tertulis tentang kebutuhan anak, bentuk akomodasi yang diperlukan, siapa penanggung jawab layanan, jadwal evaluasi, serta prosedur pengaduan. Simpan hasil komunikasi dan dokumen pendukung. Gunakan bahasa kolaboratif, tetapi tetap minta jawaban yang jelas. Bila ada dugaan diskriminasi, cari pendampingan dari lembaga yang kompeten.' },
  { q: 'Apakah artikel ini memberi nasihat hukum?', a: 'Tidak. Artikel ini adalah ringkasan edukasi dari sumber resmi yang tersedia saat penulisan. Peraturan dapat memiliki perubahan, aturan turunan, dan penerapan berbeda menurut sektor serta daerah. Untuk sengketa, pengaduan, atau keputusan yang berdampak besar, konsultasikan dokumen lengkap dengan advokat, lembaga bantuan hukum, atau pendamping disabilitas yang kompeten.' },
];
let legalBody = bodyStart(
  'Peraturan pemerintah tentang disabilitas di Indonesia terdiri dari beberapa aturan dengan fokus berbeda, antara lain perencanaan dan evaluasi hak penyandang disabilitas, akomodasi yang layak di pendidikan, kesejahteraan sosial, aksesibilitas, serta Unit Layanan Disabilitas. Untuk pembaca keluarga dan sekolah, aturan yang paling dekat dengan pendidikan adalah PP Nomor 13 Tahun 2020. Membaca judul, ruang lingkup, dan sumber resmi adalah langkah penting sebelum mengambil kesimpulan hukum.',
  'Topik peraturan pemerintah tentang disabilitas sering dicari ketika orang tua ingin memahami hak pendidikan, akses layanan, bantuan sosial, atau tanggung jawab pemerintah daerah. Tantangannya, dokumen hukum memakai istilah yang saling terkait dan satu hak dapat dijelaskan oleh beberapa aturan. Artikel ini menyusun peta sederhana, bukan menggantikan pembacaan naskah peraturan. Ringkasan di bawah menggunakan sumber resmi pemerintah dan membedakan aturan yang mengatur perencanaan, pendidikan, kesejahteraan sosial, serta ketenagakerjaan. Pembaca dapat membandingkannya dengan artikel '+il('disabilitas-adalah','pengertian disabilitas')+' dan '+il('hak-pendidikan-anak-disabilitas-intelektual','hak pendidikan anak disabilitas intelektual')+'.',
  [['peta-aturan','Peta aturan'],['pp70','PP 70 Tahun 2019'],['pp13','PP 13 Tahun 2020'],['kesejahteraan','Kesejahteraan sosial'],['aksesibilitas','Aksesibilitas dan layanan'],['praktis','Langkah praktis'],['faq','FAQ']]
);
legalBody += h2('peta-aturan', 'Peta Singkat Peraturan Pemerintah tentang Disabilitas') +
table(['Fokus','Contoh aturan','Makna untuk pembaca'],[
['Perencanaan dan evaluasi hak','PP 70 Tahun 2019','Menyusun arah, program, anggaran, dan evaluasi pemenuhan hak.'],
['Kesejahteraan sosial','PP 52 Tahun 2019','Mengatur rehabilitasi sosial, jaminan sosial, pemberdayaan, dan perlindungan sosial.'],
['Akomodasi pendidikan','PP 13 Tahun 2020','Menjelaskan dukungan agar peserta didik disabilitas dapat menikmati pendidikan.'],
['Aksesibilitas dan perlindungan','PP 42 Tahun 2020','Membahas permukiman, pelayanan publik, dan perlindungan dari bencana.'],
['Ketenagakerjaan','PP 60 Tahun 2020','Mengatur Unit Layanan Disabilitas bidang ketenagakerjaan.'],
]) +
p('Daftar tersebut bukan daftar seluruh regulasi. Undang-Undang Nomor 8 Tahun 2016 menjadi salah satu dasar penting, sementara peraturan pemerintah memberi rincian pelaksanaan pada bidang tertentu. Sekretariat Kabinet merangkum bahwa pada 2019 dan 2020 pemerintah menerbitkan beberapa aturan turunan terkait hak penyandang disabilitas. Karena aturan dapat berubah atau dilengkapi aturan menteri, gunakan tautan dokumen resmi dan cek tanggal akses ketika membuat keputusan.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_115830.webp','Papan kegiatan pendidikan di lingkungan YUKA','Dokumentasi lingkungan kegiatan YUKA. Foto ini bukan dokumen hukum dan tidak menggantikan naskah peraturan.') +
h2('pp70', 'PP Nomor 70 Tahun 2019: Perencanaan dan Evaluasi Hak') +
p('PP Nomor 70 Tahun 2019 berfokus pada perencanaan, penyelenggaraan, dan evaluasi penghormatan, pelindungan, serta pemenuhan hak penyandang disabilitas. Gagasan pentingnya adalah pembangunan inklusif tidak cukup diukur dari ada atau tidaknya satu kegiatan. Pemerintah perlu memasukkan kebutuhan penyandang disabilitas ke dalam perencanaan, penganggaran, pelaksanaan, pemantauan, dan evaluasi. Dengan kerangka ini, data dan partisipasi penyandang disabilitas menjadi bagian dari siklus kebijakan.') +
p('Untuk keluarga, dampaknya dapat dipahami melalui pertanyaan sederhana. Apakah program di daerah mencantumkan target aksesibilitas? Apakah sekolah dan layanan publik memiliki mekanisme menerima masukan? Apakah anggaran dan indikatornya dapat diperiksa? Pertanyaan ini tidak otomatis membuktikan pelanggaran, tetapi membantu warga meminta informasi yang lebih jelas. Dalam konteks sekolah inklusi, orang tua dapat mengaitkannya dengan artikel '+il('indikator-keberhasilan-sekolah-inklusi','indikator keberhasilan sekolah inklusi')+' dan '+il('peran-orang-tua-pendidikan-inklusi','peran orang tua dalam pendidikan inklusi')+'.') +
h2('pp13', 'PP Nomor 13 Tahun 2020: Akomodasi yang Layak di Pendidikan') +
p('PP Nomor 13 Tahun 2020 menjelaskan Akomodasi yang Layak untuk Peserta Didik Penyandang Disabilitas. Sekretariat Kabinet menyebut tujuan aturan ini adalah menjamin terselenggara atau terfasilitasinya pendidikan bagi peserta didik penyandang disabilitas pada semua jalur, jenjang, dan jenis pendidikan, baik inklusif maupun khusus. Fasilitasi pemerintah pusat dan daerah paling sedikit berkaitan dengan dukungan anggaran, sarana prasarana, pendidik dan tenaga kependidikan, serta kurikulum.') +
p('Akomodasi yang layak bukan berarti semua anak mendapat perlakuan yang persis sama. Akomodasi adalah modifikasi atau penyesuaian yang diperlukan agar anak dapat menikmati hak secara setara. Bentuknya perlu dirancang berdasarkan kebutuhan anak, misalnya cara menyampaikan instruksi, waktu pengerjaan, akses fisik, komunikasi, materi, atau dukungan tenaga. Orang tua dapat meminta pertemuan untuk membahas kebutuhan tersebut dan menuliskan hasil kesepakatan. Artikel '+il('adaptasi-soal-ujian-untuk-anak-abk','adaptasi soal ujian')+' memberikan contoh area pembelajaran yang sering perlu dibahas.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/IMG_8415.webp','Kegiatan pendampingan belajar di lingkungan YUKA','Dokumentasi kegiatan belajar dan pendampingan YUKA, digunakan sebagai konteks pendidikan inklusif.') +
h2('kesejahteraan', 'PP Nomor 52 Tahun 2019 dan Rehabilitasi Sosial') +
p('PP Nomor 52 Tahun 2019 mengatur penyelenggaraan kesejahteraan sosial bagi penyandang disabilitas. Sumber resmi JDIH BPK menjelaskan bahwa cakupannya meliputi rehabilitasi sosial, jaminan sosial, pemberdayaan sosial, dan perlindungan sosial. Rehabilitasi sosial dipahami sebagai proses refungsionalisasi dan pengembangan agar penyandang disabilitas dapat melaksanakan fungsi sosial secara wajar. Pendekatan ini berbeda dari anggapan bahwa layanan hanya berupa bantuan sesaat.') +
p('Aturan tersebut juga menekankan bahwa penyelenggaraan perlu memperhatikan ragam, kebutuhan, dan tingkat kerentanan penyandang disabilitas. Artinya, layanan seharusnya tidak memakai satu paket yang sama untuk semua orang. Kebutuhan anak, keluarga, komunitas, dan orang dewasa dapat berbeda. Pembaca yang ingin memahami jalur layanan pemerintah dapat membaca artikel '+il('apa-saja-program-pemerintah-untuk-penyandang-disabilitas','program pemerintah untuk penyandang disabilitas')+' dan '+il('cara-mengajukan-bantuan-pemerintah-untuk-anak-disabilitas','cara mengajukan bantuan pemerintah untuk anak disabilitas')+'.') +
h2('aksesibilitas', 'Aksesibilitas, Unit Layanan, dan Tanggung Jawab') +
p('Peraturan tentang disabilitas menghubungkan hak dengan kelembagaan. Unit Layanan Disabilitas dapat menjadi bagian dari institusi yang membantu menyediakan layanan, fasilitas, koordinasi, dan dukungan. Dalam pendidikan, pembentukan dan fungsi unit perlu dibaca bersama PP Nomor 13 Tahun 2020 serta kebijakan sektor pendidikan. Dalam ketenagakerjaan, PP Nomor 60 Tahun 2020 mengatur kewajiban pemerintah daerah memiliki ULD Ketenagakerjaan pada dinas terkait di tingkat provinsi dan kabupaten atau kota.') +
p('Aksesibilitas juga tidak hanya berarti ramp. Akses dapat mencakup informasi yang dapat dipahami, komunikasi, ruang yang aman, prosedur pengaduan, transportasi, alat bantu, penyesuaian layanan, serta kesiapan petugas. Saat menilai satu layanan, lihat alurnya dari awal sampai selesai. Apakah seseorang dapat menemukan informasi, datang ke lokasi, memahami instruksi, menyampaikan kebutuhan, menerima layanan, dan mengajukan keberatan? Artikel '+il('apa-yang-dimaksud-dengan-fasilitas-pendidikan','fasilitas pendidikan')+' dapat membantu memperluas pembahasan tentang lingkungan belajar.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/IMG_8417_latar_belakang.webp','Suasana belajar dan interaksi pendamping dengan peserta kegiatan','Dokumentasi suasana belajar YUKA. Penyesuaian layanan perlu dirancang berdasarkan kebutuhan, bukan hanya fasilitas fisik.') +
h2('praktis', 'Langkah Praktis untuk Orang Tua dan Sekolah') +
ul([
'Identifikasi kebutuhan anak secara spesifik, termasuk cara komunikasi, akses fisik, sensorik, kesehatan, dan pembelajaran.',
'Kumpulkan dokumen yang relevan, tetapi jangan menjadikan diagnosis sebagai satu-satunya ukuran kemampuan anak.',
'Minta pertemuan dengan sekolah atau penyedia layanan untuk membahas akomodasi, penanggung jawab, dan jadwal evaluasi.',
'Tanyakan Unit Layanan Disabilitas atau mekanisme dukungan yang tersedia di daerah dan sektor terkait.',
'Simpan komunikasi, rencana dukungan, hasil evaluasi, dan tindak lanjut secara rapi.',
'Jika terjadi hambatan atau dugaan diskriminasi, cari pendampingan dari organisasi disabilitas, lembaga bantuan hukum, atau pihak berwenang.',
]) +
p('Saat berdiskusi, gunakan kalimat yang berfokus pada hak dan kebutuhan anak. Contohnya, "Anak memerlukan instruksi tertulis dan waktu tambahan agar dapat menunjukkan pemahamannya. Bagaimana sekolah menyiapkan akomodasi ini dan kapan kita meninjau hasilnya?" Cara ini membantu dialog tetap konkret. Sekolah juga perlu mendengar suara anak sesuai usia dan kemampuannya, bukan hanya berbicara tentang anak kepada orang dewasa lain.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/IMG_8418.webp','Kegiatan bersama di ruang belajar YUKA','Dokumentasi kegiatan bersama YUKA. Peraturan perlu diterjemahkan menjadi prosedur layanan yang dapat dirasakan anak dan keluarga.') +
p('Membaca aturan juga perlu membedakan antara norma, kewajiban, dan mekanisme pelaksanaan. Sebuah pasal dapat menyatakan tujuan atau kewajiban umum, sementara petunjuk teknis menjelaskan siapa yang bertugas, dokumen apa yang dipakai, dan bagaimana evaluasi dilakukan. Karena itu, orang tua tidak perlu menghafal semua nomor pasal. Yang lebih penting adalah menemukan aturan yang sesuai bidangnya, menyimpan sumber, dan mengajukan pertanyaan yang dapat dijawab oleh sekolah atau instansi terkait.') +
p('Dalam percakapan dengan sekolah, fokuskan pembahasan pada kebutuhan anak dan bentuk akomodasinya. Misalnya, anak mungkin memerlukan materi dengan format tertentu, waktu tambahan, cara komunikasi alternatif, atau jeda sensorik. Akomodasi tidak boleh membuat anak kehilangan kesempatan belajar. Sekolah dapat menyusun rencana, menetapkan penanggung jawab, dan mengevaluasi apakah penyesuaian tersebut membantu anak berpartisipasi. Bila kebutuhan berubah, rencana perlu diperbarui melalui dialog dengan keluarga dan anak.') +
p('Jika pembaca menemukan istilah hukum yang tidak dipahami, jangan mengambil kesimpulan dari judul berita saja. Baca dokumen atau ringkasan resmi, perhatikan tanggal berlaku, dan cek apakah ada aturan pelaksana. Untuk persoalan yang menyangkut penolakan layanan, diskriminasi, atau sengketa, kumpulkan kronologi dan bukti komunikasi. Pendamping disabilitas atau bantuan hukum dapat membantu menerjemahkan pilihan yang tersedia tanpa meminta keluarga bertindak secara terburu-buru.') +
p('Kebijakan publik yang inklusif seharusnya terlihat dalam pengalaman sehari-hari: informasi dapat diakses, petugas siap membantu, ruang dapat digunakan, dan mekanisme pengaduan benar-benar berjalan. Peraturan memberi kerangka, tetapi pelaksanaan membutuhkan anggaran, kapasitas, data, koordinasi, serta partisipasi penyandang disabilitas. Karena itu, warga dapat ikut memantau dan memberi masukan secara aman melalui forum atau kanal resmi yang tersedia.') +
p('Orang tua juga dapat memakai prinsip dokumentasi sederhana. Catat tanggal pertemuan, kebutuhan yang disampaikan, respons sekolah, bentuk penyesuaian yang dicoba, dan tanggal peninjauan berikutnya. Catatan ini membantu semua pihak melihat apakah kesepakatan dijalankan, sekaligus mengurangi salah paham. Dokumentasi tidak berarti orang tua harus berkonflik dengan sekolah. Justru, informasi yang tertata dapat membuat pembicaraan lebih tenang, terukur, dan berorientasi pada kepentingan terbaik anak.') +
p('Bahasa yang dipakai dalam dokumen dan pertemuan juga penting. Hindari menggambarkan anak hanya dari kekurangannya. Jelaskan kekuatan, cara belajar, minat, serta dukungan yang membuat anak dapat berpartisipasi. Pendekatan ini membantu sekolah merancang akomodasi yang tidak sekadar bersifat administratif. Bila ada istilah yang terasa merendahkan, keluarga dapat meminta penjelasan dan mengusulkan bahasa yang menghormati martabat anak. Perubahan kecil pada cara berkomunikasi sering menjadi awal perubahan layanan yang lebih inklusif. Catatan yang sama dapat membantu evaluasi berikutnya. Keluarga juga dapat menanyakan siapa yang bertanggung jawab menindaklanjuti kesepakatan, kapan hasilnya ditinjau, dan bagaimana mengajukan perubahan bila kebutuhan anak berkembang.') +
h2('kesimpulan', 'Kesimpulan') +
p('Peraturan pemerintah tentang disabilitas membentuk jaringan aturan, bukan satu dokumen tunggal. PP 70 Tahun 2019 memberi kerangka perencanaan dan evaluasi. PP 13 Tahun 2020 berfokus pada akomodasi pendidikan. PP 52 Tahun 2019 mengatur kesejahteraan sosial, sementara aturan lain membahas aksesibilitas dan Unit Layanan Disabilitas. Gunakan ringkasan ini sebagai peta awal, lalu baca naskah resmi yang sesuai dengan kebutuhan dan konsultasikan persoalan hukum khusus kepada pihak kompeten.') + faqHtml(legalFaq);

const rehabFaq = [
  { q: 'Apa itu Program Rehabilitasi Sosial Anak Disabilitas Kemensos?', a: 'Layanan rehabilitasi sosial Kemensos untuk anak disabilitas berada dalam kerangka ATENSI dan layanan rehabilitasi sosial. Pendekatannya dapat berbasis keluarga, komunitas, atau residensial sesuai kebutuhan dan asesmen. Layanan dapat mencakup dukungan kebutuhan hidup layak, pengasuhan, terapi, dukungan keluarga, aksesibilitas, bantuan sosial, serta pelatihan tertentu.' },
  { q: 'Apa kepanjangan ATENSI?', a: 'ATENSI adalah Asistensi Rehabilitasi Sosial. Kemensos menjelaskan ATENSI sebagai layanan rehabilitasi sosial dengan pendekatan keluarga, komunitas, dan residensial. Sasaran kerja mencakup beberapa kelompok pemerlu atensi sosial, termasuk anak rentan dan penyandang disabilitas. Bentuk layanan ditentukan berdasarkan kebutuhan, asesmen, dan ketersediaan unit pelaksana.' },
  { q: 'Apakah semua anak disabilitas otomatis mendapat bantuan?', a: 'Tidak otomatis. Akses layanan memerlukan proses identifikasi, asesmen, verifikasi, dan penentuan bentuk dukungan. Kriteria dan prosedur dapat berbeda menurut jenis layanan serta unit pelaksana. Orang tua sebaiknya meminta informasi dari dinas sosial, sentra, atau unit layanan resmi, lalu menyiapkan dokumen yang diminta tanpa mengunggah data pribadi ke pihak yang tidak jelas.' },
  { q: 'Apa saja layanan yang dapat tersedia?', a: 'Program ATENSI dapat mencakup kebutuhan hidup layak, perawatan atau pengasuhan anak, dukungan keluarga, terapi fisik, terapi psikososial, terapi mental spiritual, pelatihan vokasional, kewirausahaan, bantuan sosial, dan dukungan aksesibilitas. Tidak semua penerima memperoleh semua jenis layanan. Bentuk dukungan mengikuti hasil asesmen dan rencana layanan.' },
  { q: 'Bagaimana cara menghubungi Kemensos untuk layanan anak disabilitas?', a: 'Mulailah dari dinas sosial kabupaten atau kota dan tanyakan sentra atau unit pelaksana teknis Kemensos yang melayani wilayah Anda. Jelaskan kebutuhan secara ringkas dan minta kanal resmi untuk pendaftaran atau asesmen. Gunakan nomor dan situs yang tercantum di halaman resmi pemerintah. Hindari membayar pihak yang menjanjikan kelulusan bantuan.' },
  { q: 'Apakah rehabilitasi sosial sama dengan pengobatan medis?', a: 'Tidak. Rehabilitasi sosial berfokus pada keberfungsian sosial, kemandirian, dukungan keluarga, aksesibilitas, dan partisipasi. Terapi medis atau layanan kesehatan memiliki tujuan dan kewenangan berbeda. Keduanya dapat saling melengkapi, tetapi orang tua perlu mengikuti rujukan profesional dan tidak menghentikan pengobatan hanya karena menerima layanan sosial.' },
  { q: 'Apa yang harus diperhatikan keluarga saat menerima layanan?', a: 'Keluarga perlu meminta penjelasan tujuan, jenis layanan, jadwal, pihak yang bertanggung jawab, cara evaluasi, dan mekanisme pengaduan. Tanyakan bagaimana data anak disimpan dan siapa yang dapat mengaksesnya. Simpan bukti komunikasi. Jika layanan tidak sesuai kebutuhan atau ada perlakuan yang merendahkan, keluarga berhak menyampaikan keberatan melalui kanal resmi.' },
];
let rehabBody = bodyStart(
  'Program rehabilitasi sosial anak disabilitas Kemensos umumnya dipahami melalui kerangka ATENSI, yaitu Asistensi Rehabilitasi Sosial. Layanan ini menggunakan pendekatan berbasis keluarga, komunitas, dan residensial. Bentuk dukungannya dapat meliputi kebutuhan hidup layak, pengasuhan, dukungan keluarga, terapi sosial, aksesibilitas, bantuan sosial, serta pelatihan. Anak tidak otomatis menerima semua layanan, karena bentuk dukungan perlu ditentukan melalui identifikasi dan asesmen.',
  'Keluarga sering mencari informasi ini ketika membutuhkan dukungan untuk anak dengan disabilitas, anak rentan, atau kondisi sosial yang membuat pengasuhan dan akses layanan menjadi berat. Informasi di internet dapat mencampur bantuan sosial, terapi kesehatan, rehabilitasi sosial, dan program pemerintah daerah. Artikel ini memisahkan istilah tersebut agar pembaca memiliki gambaran sebelum menghubungi layanan resmi. Rujukan utama berasal dari halaman Program ATENSI Kemensos, pedoman operasional ATENSI anak, dan glosarium JDIH Kemensos. Untuk konteks hak dan kebutuhan, pembaca dapat melihat '+il('disabilitas-adalah','pengertian disabilitas')+' serta '+il('apa-saja-terapi-anak-berkebutuhan-khusus','jenis terapi anak berkebutuhan khusus')+'.',
  [['atensi','Apa itu ATENSI'],['sasaran','Sasaran layanan'],['bentuk','Bentuk rehabilitasi sosial'],['akses','Cara mencari akses'],['peran','Peran keluarga dan komunitas'],['aman','Catatan keamanan'],['faq','FAQ']]
);
rehabBody += h2('atensi', 'Apa Itu ATENSI dari Kemensos?') +
p('Halaman Program ATENSI Kemensos menjelaskan bahwa ATENSI adalah layanan rehabilitasi sosial dengan pendekatan berbasis keluarga, komunitas, dan residensial. Pendekatan keluarga dilakukan di tengah keluarga dengan mendorong peran aktif anggota keluarga. Pendekatan komunitas memaksimalkan potensi lingkungan sekitar. Pendekatan residensial menjadi alternatif terakhir atau layanan perlindungan dan pengembangan rehabilitasi sosial lanjutan ketika kebutuhan anak tidak dapat dipenuhi dengan aman melalui pilihan lain.') +
p('Istilah rehabilitasi sosial tidak berarti anak harus diubah agar terlihat sama dengan anak lain. Dalam kerangka kesejahteraan sosial, rehabilitasi sosial bertujuan memulihkan atau mengembangkan kemampuan agar seseorang dapat menjalankan fungsi sosial secara wajar. Bagi anak, fokusnya dapat berupa komunikasi, kemandirian, partisipasi, hubungan dengan keluarga, akses pendidikan, dan keamanan. Intervensi perlu menghormati martabat, pilihan, tahap perkembangan, dan kondisi kesehatan anak.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/IMG_8421.webp','Kegiatan belajar bersama dalam lingkungan YUKA','Dokumentasi kegiatan belajar YUKA. Rehabilitasi sosial perlu mendukung partisipasi anak dalam lingkungan yang aman.') +
h2('sasaran', 'Siapa yang Dapat Menjadi Sasaran?') +
p('Program ATENSI memiliki sasaran kerja yang luas. Halaman resmi Kemensos menyebut kelompok seperti anak rentan, penyandang disabilitas, lansia terlantar, korban kekerasan, korban bencana, fakir miskin, dan kelompok lain yang memerlukan atensi sosial. Pada layanan anak, pedoman operasional ATENSI anak ditujukan untuk anak yang memerlukan perlindungan khusus, balita, anak jalanan, serta anak yang membutuhkan pengembangan fungsi sosial. Detail penerimaan tetap ditentukan oleh unit layanan dan hasil asesmen.') +
p('Untuk keluarga anak disabilitas, kebutuhan dapat mencakup alat bantu, dukungan pengasuhan, akses sekolah, terapi sosial, pelatihan kemandirian, atau bantuan kebutuhan dasar. Jangan menganggap satu dokumen diagnosis otomatis menjamin jenis bantuan tertentu. Sebaliknya, jelaskan fungsi anak sehari-hari, hambatan akses, kondisi keluarga, dan dukungan yang sudah tersedia. Informasi ini membantu petugas menilai kebutuhan secara lebih utuh. Artikel '+il('cara-mengajukan-bantuan-pemerintah-untuk-anak-disabilitas','cara mengajukan bantuan pemerintah')+' dapat dibaca sebagai pendamping topik.') +
h2('bentuk', 'Bentuk Layanan Rehabilitasi Sosial') +
table(['Area dukungan','Contoh bentuk layanan','Catatan untuk keluarga'],[
['Kebutuhan hidup layak','Bantuan untuk kebutuhan dasar sesuai program','Tanyakan kriteria, durasi, dan mekanisme penyaluran.'],
['Pengasuhan dan dukungan keluarga','Konseling, pendampingan, dan penguatan peran keluarga','Dukungan harus menghormati kondisi dan keputusan keluarga.'],
['Terapi sosial','Terapi fisik, psikososial, atau mental spiritual sesuai kebutuhan','Bukan pengganti layanan medis ketika anak memerlukannya.'],
['Aksesibilitas','Alat bantu atau penyesuaian yang mendukung aktivitas','Kesesuaian alat perlu dinilai, bukan hanya diberikan.'],
['Vokasional dan kewirausahaan','Pelatihan keterampilan dan pengembangan usaha','Untuk anak, harus sesuai usia, keamanan, dan tujuan perkembangan.'],
]) +
p('Kemensos juga menjelaskan bahwa layanan dapat berlangsung melalui Unit Pelaksana Teknis yang tersebar di berbagai wilayah. Bentuk layanan, jadwal, dan kapasitas setiap unit dapat berbeda. Karena itu, halaman program nasional sebaiknya menjadi pintu untuk memahami konsep, sedangkan informasi pendaftaran perlu dikonfirmasi kepada sentra, dinas sosial, atau unit resmi. Jangan mengandalkan unggahan media sosial tanpa memeriksa apakah akun dan alamatnya benar.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_120230.webp','Suasana akses menuju ruang kegiatan YUKA','Dokumentasi suasana lingkungan kegiatan YUKA. Aksesibilitas mencakup kemudahan mencapai, memahami, dan mengikuti layanan.') +
h2('akses', 'Cara Mencari Akses Layanan') +
ul([
'Catat kebutuhan anak dan keluarga dalam bahasa sehari-hari, termasuk hambatan aktivitas, komunikasi, mobilitas, belajar, atau pengasuhan.',
'Hubungi dinas sosial kabupaten atau kota untuk menanyakan sentra, unit pelaksana, atau prosedur layanan yang melayani wilayah Anda.',
'Gunakan halaman resmi Kemensos dan JDIH Kemensos untuk memeriksa istilah program, pedoman, dan kanal informasi.',
'Tanyakan dokumen yang diperlukan sebelum mengirim data, misalnya identitas, kartu keluarga, surat keterangan, atau dokumen kondisi anak jika memang diminta.',
'Minta penjelasan tentang proses asesmen, rencana layanan, jadwal, evaluasi, serta mekanisme pengaduan.',
'Simpan nama petugas, tanggal komunikasi, nomor layanan, dan salinan dokumen yang dikirim.',
]) +
p('Tidak semua keluarga harus langsung menuju layanan residensial. Bila kebutuhan dapat dipenuhi dengan dukungan keluarga dan komunitas, layanan berbasis keluarga atau komunitas dapat lebih sesuai. Pilihan tersebut perlu dibahas dengan petugas berdasarkan keselamatan dan kepentingan terbaik anak. Bila ada situasi darurat, kekerasan, penelantaran, atau risiko keselamatan, keluarga perlu mencari bantuan segera melalui layanan darurat dan lembaga resmi setempat.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_115538.webp','Dokumentasi sertifikat kegiatan pelatihan YUKA','Dokumentasi sertifikat kegiatan YUKA. Sertifikat ini bukan bukti kelulusan atau jaminan penerimaan program ATENSI.') +
h2('peran', 'Peran Keluarga dan Komunitas') +
p('Keluarga bukan sekadar penerima bantuan. Keluarga membawa pengetahuan tentang kebiasaan, komunikasi, kekuatan, dan kebutuhan anak. Saat asesmen, sampaikan rutinitas yang berhasil, situasi yang sulit, cara anak mengekspresikan sakit atau tidak nyaman, serta dukungan yang sudah pernah dicoba. Informasi itu membantu rencana layanan menjadi lebih realistis. Namun keluarga juga tidak boleh dibebani seluruh tanggung jawab. Pemerintah, sekolah, layanan kesehatan, dan komunitas perlu berbagi peran.') +
p('Komunitas dapat membantu melalui lingkungan yang ramah, akses informasi, dukungan tetangga, kegiatan aman, atau rujukan ke layanan resmi. Bantuan komunitas tidak boleh mengambil foto, menyebarkan cerita, atau mengumpulkan data anak tanpa izin. Prinsip perlindungan data perlu diterapkan terutama ketika program memakai grup pesan atau formulir daring. Artikel '+il('dukungan-keluarga-anak-abk','dukungan keluarga anak ABK')+' dan '+il('inklusi-sosial','inklusi sosial')+' dapat membantu memperluas pembahasan partisipasi.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_115544.webp','Dokumentasi sertifikat pelatihan di lingkungan YUKA','Dokumentasi kegiatan pelatihan YUKA. Pelatihan adalah salah satu bentuk penguatan, bukan pengganti asesmen kebutuhan anak.') +
h2('aman', 'Catatan Keamanan dan Verifikasi Informasi') +
p('Waspadai pihak yang meminta biaya untuk menjamin bantuan, meminta kata sandi, meminta kode OTP, atau meminta foto dokumen anak melalui nomor yang tidak dapat diverifikasi. Program pemerintah dapat memiliki proses administrasi, tetapi keluarga harus memperoleh penjelasan resmi tentang dasar, tujuan, dan kanal pembayaran bila ada. Jangan mengirim data sensitif ke formulir yang tidak mencantumkan identitas lembaga dan kebijakan privasi. Jika ragu, hentikan pengiriman data dan hubungi kanal resmi.') +
p('Pastikan informasi yang dibaca masih berlaku. Halaman Program ATENSI, pedoman operasional, dan glosarium JDIH Kemensos adalah titik awal yang lebih kuat daripada unggahan tanpa sumber. Glosarium membantu memahami istilah seperti ATENSI, PPKS, pendamping rehabilitasi sosial, dan penyandang disabilitas. Walaupun demikian, glosarium bukan surat keputusan penerimaan. Keputusan layanan tetap mengikuti asesmen dan prosedur unit pelaksana.') +
makeBodyFigure('Dokumentasi/21 Jan 2026/20260121_115548.webp','Dokumentasi sertifikat kegiatan YUKA dalam bingkai','Dokumentasi aset kegiatan YUKA. Pembaca perlu membedakan dokumentasi internal dari bukti status program pemerintah.') +
p('Sebelum mendaftar, keluarga dapat membuat ringkasan satu halaman tentang kondisi dan kebutuhan anak. Tuliskan aktivitas yang sudah dapat dilakukan, aktivitas yang memerlukan bantuan, hambatan yang paling mengganggu, serta tujuan yang ingin dicapai dalam beberapa bulan. Ringkasan ini bukan pengganti asesmen, tetapi membantu percakapan awal lebih terarah. Bila ada laporan dari sekolah, tenaga kesehatan, atau terapis, bawa salinan yang relevan dan tutup informasi yang tidak diperlukan oleh petugas.') +
p('Rencana layanan juga perlu memiliki ukuran kemajuan yang masuk akal. Misalnya, anak lebih mampu mengikuti rutinitas, menggunakan alat bantu, berkomunikasi untuk meminta bantuan, atau mengikuti kegiatan bersama. Ukuran tidak selalu berupa angka besar. Perubahan kecil dapat berarti ketika anak sebelumnya tidak memiliki akses terhadap aktivitas. Keluarga dapat meminta jadwal evaluasi agar dukungan tidak berhenti tanpa penjelasan dan agar strategi yang tidak efektif dapat diperbaiki.') +
p('Asesmen sebaiknya dilakukan dengan melihat kehidupan anak secara utuh. Petugas dapat menanyakan kondisi rumah, hubungan pengasuhan, akses sekolah, kesehatan, komunikasi, mobilitas, keamanan, dan dukungan yang sudah dimiliki. Keluarga berhak meminta penjelasan tentang tujuan pertanyaan dan penggunaan informasi tersebut. Bila anak mampu berkomunikasi, pendapat dan kenyamanannya perlu didengar sesuai usia serta kapasitasnya. Anak bukan sekadar objek program, melainkan pihak yang mengalami langsung dampak layanan.') +
p('Evaluasi layanan tidak harus menunggu masalah menjadi besar. Keluarga dapat meminta pertemuan singkat bila jadwal tidak cocok, alat bantu tidak sesuai, atau strategi pendampingan membuat anak tertekan. Sampaikan contoh kejadian, waktu, dan dampaknya. Hindari membagikan data anak di ruang publik untuk mencari perhatian. Gunakan mekanisme pengaduan resmi dan simpan bukti komunikasi agar tindak lanjut dapat ditelusuri.') +
p('Ketika layanan melibatkan beberapa pihak, mintalah pembagian peran yang jelas. Misalnya, keluarga mendampingi rutinitas di rumah, sekolah menyesuaikan kegiatan belajar, tenaga kesehatan menangani kebutuhan medis, dan petugas rehabilitasi sosial membantu keberfungsian sosial. Koordinasi seperti ini mencegah keluarga menerima saran yang saling bertentangan. Dengan persetujuan yang tepat, ringkasan kebutuhan dapat dibagikan secara terbatas kepada pihak yang memang bertanggung jawab.') +
p('Keluarga juga perlu menyiapkan rencana bila layanan berhenti, petugas berganti, atau anak memasuki tahap perkembangan baru. Minta nama kontak pengganti, cara memperbarui data, dan jadwal peninjauan. Rencana transisi membantu anak tetap memperoleh dukungan ketika pindah sekolah, pindah domisili, atau beralih dari layanan anak ke layanan berikutnya. Semua keputusan harus mengutamakan keselamatan, martabat, serta partisipasi anak. Simpan rencana ini bersama dokumen penting lainnya agar mudah dibawa saat berkonsultasi. Tinjau rencana secara berkala bersama pihak terkait dan catat hasilnya secara tertulis, lalu perbarui bila ada perubahan penting.') +
h2('kesimpulan', 'Kesimpulan') +
p('Program rehabilitasi sosial anak disabilitas Kemensos perlu dipahami melalui pendekatan ATENSI dan layanan rehabilitasi sosial. Ada pilihan berbasis keluarga, komunitas, dan residensial. Bentuk dukungan dapat meliputi kebutuhan dasar, pengasuhan, dukungan keluarga, terapi sosial, aksesibilitas, bantuan sosial, dan pelatihan. Langkah paling aman adalah memulai dari kanal resmi, menjelaskan kebutuhan anak, mengikuti asesmen, menjaga dokumen, dan meminta rencana layanan yang dapat dipahami.') + faqHtml(rehabFaq);

